const body = $input.first().json.body;
const type = body.type;

const brand = '#1a3c6e';
const accent = '#2563eb';
const light = '#f0f4ff';
const success = '#16a34a';
const danger = '#dc2626';
const warning = '#d97706';
const text = '#1e293b';
const muted = '#64748b';
const border = '#e2e8f0';

const base = (headerColor, headerIcon, headerTitle, bodyContent) => `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${headerTitle}</title>
</head>
<body style="margin:0;padding:0;background:#f1f5f9;font-family:'Segoe UI',Arial,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:40px 0;">
    <tr><td align="center">
      <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);">

        <!-- Header -->
        <tr>
          <td style="background:linear-gradient(135deg,${headerColor} 0%,${accent} 100%);padding:40px 48px;text-align:center;">
            <div style="font-size:40px;margin-bottom:12px;">${headerIcon}</div>
            <h1 style="margin:0;color:#ffffff;font-size:24px;font-weight:700;letter-spacing:-0.5px;">${headerTitle}</h1>
            <p style="margin:8px 0 0;color:rgba(255,255,255,0.8);font-size:13px;letter-spacing:2px;text-transform:uppercase;">ClubHub Platform</p>
          </td>
        </tr>

        <!-- Body -->
        <tr>
          <td style="padding:48px;color:${text};">
            ${bodyContent}
          </td>
        </tr>

        <!-- Footer -->
        <tr>
          <td style="background:#f8fafc;padding:28px 48px;border-top:1px solid ${border};">
            <table width="100%" cellpadding="0" cellspacing="0">
              <tr>
                <td style="text-align:center;">
                  <p style="margin:0 0 8px;font-size:15px;font-weight:700;color:${brand};">ClubHub</p>
                  <p style="margin:0;font-size:12px;color:${muted};">Smart Club & Event Management Platform</p>
                  <p style="margin:12px 0 0;font-size:11px;color:#94a3b8;">This is an automated email. Please do not reply directly to this message.</p>
                </td>
              </tr>
            </table>
          </td>
        </tr>

      </table>
    </td></tr>
  </table>
</body>
</html>`;

const infoRow = (label, value) =>
  `<tr><td style="padding:6px 0;font-size:14px;color:#64748b;width:130px;">${label}</td><td style="padding:6px 0;font-size:14px;color:#1e293b;font-weight:600;">${value}</td></tr>`;

const btn = (url, label, color='#2563eb') =>
  `<a href="${url}" style="display:inline-block;background:${color};color:#ffffff;text-decoration:none;padding:14px 32px;border-radius:8px;font-size:15px;font-weight:600;letter-spacing:0.3px;margin-top:8px;">${label}</a>`;

const greeting = (name) =>
  `<p style="margin:0 0 24px;font-size:22px;font-weight:700;color:#1a3c6e;">Hi ${name},</p>`;

const divider = `<hr style="border:none;border-top:1px solid #e2e8f0;margin:28px 0;"/>`;

let toEmail = '', subject = '', html = '';

if (type === 'user_registration') {
  toEmail = body.email;
  subject = 'Welcome to ClubHub — Your Account is Ready!';
  const roleLabel = body.role === 'admin' ? 'Administrator' : body.role === 'leader' ? 'Club Leader' : 'Student';
  const roleBadgeColor = body.role === 'admin' ? '#7c3aed' : body.role === 'leader' ? '#d97706' : '#2563eb';
  html = base(
    brand, '🎓', 'Welcome to ClubHub!',
    `${greeting(body.name)}
    <p style="margin:0 0 24px;font-size:15px;line-height:1.7;color:#475569;">Your account has been created successfully. You're all set to explore everything ClubHub has to offer.</p>
    <div style="background:#f0f4ff;border-radius:12px;padding:20px 24px;margin:0 0 28px;">
      <table cellpadding="0" cellspacing="0">
        ${infoRow('Name', body.name)}
        ${infoRow('Email', body.email)}
        ${infoRow('Role', `<span style="background:${roleBadgeColor};color:#fff;padding:2px 10px;border-radius:20px;font-size:12px;">${roleLabel}</span>`)}
      </table>
    </div>
    <p style="margin:0 0 20px;font-size:15px;color:#475569;">Here's what you can do with your account:</p>
    <table cellpadding="0" cellspacing="0" style="width:100%;">
      <tr><td style="padding:8px 0;"><span style="color:#2563eb;font-weight:700;">→</span> <span style="font-size:14px;color:#1e293b;">Browse and join clubs that match your interests</span></td></tr>
      <tr><td style="padding:8px 0;"><span style="color:#2563eb;font-weight:700;">→</span> <span style="font-size:14px;color:#1e293b;">Register for upcoming events and get QR tickets</span></td></tr>
      <tr><td style="padding:8px 0;"><span style="color:#2563eb;font-weight:700;">→</span> <span style="font-size:14px;color:#1e293b;">Track attendance and download certificates</span></td></tr>
    </table>
    ${divider}
    <div style="text-align:center;">${btn('http://localhost:5173/login', 'Login to ClubHub')}</div>`
  );

} else if (type === 'FORGOT_PASSWORD') {
  toEmail = body.email;
  subject = 'Reset Your Password — ClubHub';
  html = base(
    '#dc2626', '🔐', 'Password Reset Request',
    `${greeting(body.name)}
    <p style="margin:0 0 24px;font-size:15px;line-height:1.7;color:#475569;">We received a request to reset the password for your ClubHub account. Click the button below to create a new password.</p>
    <div style="background:#fef2f2;border:1px solid #fecaca;border-radius:12px;padding:20px 24px;margin:0 0 28px;">
      <p style="margin:0;font-size:14px;color:#dc2626;"><strong>⚠️ This link will expire in 15 minutes.</strong> If you didn't request a password reset, you can safely ignore this email.</p>
    </div>
    <div style="text-align:center;margin:32px 0;">${btn(body.resetLink, 'Reset My Password', '#dc2626')}</div>
    <p style="margin:0;font-size:13px;color:#94a3b8;text-align:center;">If the button doesn't work, copy and paste this link into your browser:<br><span style="color:#2563eb;word-break:break-all;">${body.resetLink}</span></p>`
  );

} else if (type === 'leader_appointed') {
  toEmail = body.email;
  subject = `You're Now Leader of ${body.clubName} — ClubHub`;
  html = base(
    '#d97706', '👑', 'Club Leader Appointed',
    `${greeting(body.name)}
    <p style="margin:0 0 24px;font-size:15px;line-height:1.7;color:#475569;">Congratulations! You have been appointed as the <strong>Club Leader</strong> of <strong>${body.clubName}</strong>. This is a great responsibility and we're excited to have you lead!</p>
    <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:12px;padding:20px 24px;margin:0 0 28px;">
      <table cellpadding="0" cellspacing="0">
        ${infoRow('Club', body.clubName)}
        ${infoRow('Your Role', '<span style="background:#d97706;color:#fff;padding:2px 10px;border-radius:20px;font-size:12px;">Club Leader</span>')}
      </table>
    </div>
    <p style="margin:0 0 16px;font-size:15px;color:#475569;">As a leader, you can now:</p>
    <table cellpadding="0" cellspacing="0" style="width:100%;">
      <tr><td style="padding:8px 0;"><span style="color:#d97706;font-weight:700;">→</span> <span style="font-size:14px;color:#1e293b;">Approve or reject membership requests</span></td></tr>
      <tr><td style="padding:8px 0;"><span style="color:#d97706;font-weight:700;">→</span> <span style="font-size:14px;color:#1e293b;">Create and manage club events</span></td></tr>
      <tr><td style="padding:8px 0;"><span style="color:#d97706;font-weight:700;">→</span> <span style="font-size:14px;color:#1e293b;">Mark attendance using QR code scanner</span></td></tr>
    </table>
    ${divider}
    <div style="text-align:center;">${btn('http://localhost:5173/login', 'Go to My Dashboard', '#d97706')}</div>`
  );

} else if (type === 'membership_approved') {
  toEmail = body.email;
  subject = `Membership Approved — Welcome to ${body.clubName}!`;
  html = base(
    success, '✅', 'Membership Approved',
    `${greeting(body.name)}
    <p style="margin:0 0 24px;font-size:15px;line-height:1.7;color:#475569;">Great news! Your request to join <strong>${body.clubName}</strong> has been <strong style="color:#16a34a;">approved</strong>. You are now an official member!</p>
    <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:12px;padding:20px 24px;margin:0 0 28px;">
      <table cellpadding="0" cellspacing="0">
        ${infoRow('Club', body.clubName)}
        ${infoRow('Status', '<span style="background:#16a34a;color:#fff;padding:2px 10px;border-radius:20px;font-size:12px;">Member</span>')}
      </table>
    </div>
    <p style="margin:0 0 20px;font-size:15px;color:#475569;">As a member you can:</p>
    <table cellpadding="0" cellspacing="0" style="width:100%;">
      <tr><td style="padding:8px 0;"><span style="color:#16a34a;font-weight:700;">→</span> <span style="font-size:14px;color:#1e293b;">View and register for club events</span></td></tr>
      <tr><td style="padding:8px 0;"><span style="color:#16a34a;font-weight:700;">→</span> <span style="font-size:14px;color:#1e293b;">Attend sessions and earn certificates</span></td></tr>
    </table>
    ${divider}
    <div style="text-align:center;">${btn('http://localhost:5173/login', 'Explore Club Events', '#16a34a')}</div>`
  );

} else if (type === 'event_approved') {
  toEmail = body.leaderEmail;
  subject = `Event Approved — "${body.eventTitle}" is Live!`;
  const fmtDate = new Date(body.eventDate).toLocaleDateString('en-IN', { weekday:'long', year:'numeric', month:'long', day:'numeric' });
  html = base(
    success, '🎉', 'Event Approved!',
    `${greeting(body.leaderName)}
    <p style="margin:0 0 24px;font-size:15px;line-height:1.7;color:#475569;">Your event has been <strong style="color:#16a34a;">approved</strong> by the admin and is now live for student registrations!</p>
    <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:12px;padding:20px 24px;margin:0 0 28px;">
      <table cellpadding="0" cellspacing="0" style="width:100%;">
        ${infoRow('Event', body.eventTitle)}
        ${infoRow('Date', fmtDate)}
        ${infoRow('Venue', body.venue)}
        ${infoRow('Status', '<span style="background:#16a34a;color:#fff;padding:2px 10px;border-radius:20px;font-size:12px;">Approved ✓</span>')}
      </table>
    </div>
    <p style="margin:0 0 20px;font-size:15px;color:#475569;">Students can now discover and register for your event. Share it with your club members!</p>
    ${divider}
    <div style="text-align:center;">${btn('http://localhost:5173/login', 'Manage My Event', '#16a34a')}</div>`
  );

} else if (type === 'event_rejected') {
  toEmail = body.leaderEmail;
  subject = `Event Not Approved — "${body.eventTitle}"`;
  html = base(
    danger, '❌', 'Event Not Approved',
    `${greeting(body.leaderName)}
    <p style="margin:0 0 24px;font-size:15px;line-height:1.7;color:#475569;">Unfortunately, your event <strong>${body.eventTitle}</strong> was <strong style="color:#dc2626;">not approved</strong> by the admin at this time.</p>
    ${body.rejectionReason ? `<div style="background:#fef2f2;border-left:4px solid #dc2626;border-radius:0 8px 8px 0;padding:16px 20px;margin:0 0 28px;"><p style="margin:0;font-size:14px;color:#dc2626;"><strong>Reason:</strong></p><p style="margin:8px 0 0;font-size:14px;color:#1e293b;">${body.rejectionReason}</p></div>` : ''}
    <p style="margin:0 0 20px;font-size:15px;color:#475569;">Don't worry — you can revise your event details and resubmit for review.</p>
    ${divider}
    <div style="text-align:center;">${btn('http://localhost:5173/login', 'Revise & Resubmit', '#dc2626')}</div>`
  );

} else if (type === 'event_registered') {
  toEmail = body.studentEmail;
  subject = `You're Registered — ${body.eventTitle}`;
  const fmtDate = new Date(body.eventDate).toLocaleDateString('en-IN', { weekday:'long', year:'numeric', month:'long', day:'numeric' });
  html = base(
    accent, '🎟️', 'Registration Confirmed!',
    `${greeting(body.studentName)}
    <p style="margin:0 0 24px;font-size:15px;line-height:1.7;color:#475569;">Your registration for the following event is <strong style="color:#2563eb;">confirmed</strong>. See you there!</p>
    <div style="background:#f0f4ff;border:1px solid #bfdbfe;border-radius:12px;padding:20px 24px;margin:0 0 28px;">
      <table cellpadding="0" cellspacing="0" style="width:100%;">
        ${infoRow('Event', body.eventTitle)}
        ${infoRow('Date', fmtDate)}
        ${infoRow('Venue', body.venue)}
        ${infoRow('Status', '<span style="background:#2563eb;color:#fff;padding:2px 10px;border-radius:20px;font-size:12px;">Registered ✓</span>')}
      </table>
    </div>
    ${body.qrCodeUrl ? `<div style="text-align:center;margin:0 0 28px;"><p style="margin:0 0 12px;font-size:14px;color:#64748b;">Your QR entry ticket is ready. Show this at the venue:</p><a href="${body.qrCodeUrl}" style="display:inline-block;background:#f0f4ff;border:2px dashed #2563eb;color:#2563eb;text-decoration:none;padding:14px 28px;border-radius:10px;font-size:14px;font-weight:700;">📲 View QR Ticket</a></div>` : ''}
    <p style="margin:0;font-size:13px;color:#94a3b8;text-align:center;">Please carry your QR code (digital or printed) to the event venue.</p>`
  );

} else if (type === 'payment_success') {
  toEmail = body.studentEmail;
  subject = `Payment Successful — ${body.eventTitle}`;
  html = base(
    success, '💳', 'Payment Confirmed!',
    `${greeting(body.studentName)}
    <p style="margin:0 0 24px;font-size:15px;line-height:1.7;color:#475569;">Your payment was <strong style="color:#16a34a;">successful</strong> and your seat is confirmed for the event.</p>
    <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:12px;padding:20px 24px;margin:0 0 28px;">
      <table cellpadding="0" cellspacing="0" style="width:100%;">
        ${infoRow('Event', body.eventTitle)}
        ${infoRow('Amount Paid', `<span style="color:#16a34a;font-size:16px;font-weight:700;">₹${body.amount}</span>`)}
        ${infoRow('Payment ID', `<span style="font-family:monospace;font-size:12px;color:#64748b;">${body.paymentId}</span>`)}
        ${infoRow('Status', '<span style="background:#16a34a;color:#fff;padding:2px 10px;border-radius:20px;font-size:12px;">Paid ✓</span>')}
      </table>
    </div>
    ${body.qrCodeUrl ? `<div style="text-align:center;margin:0 0 28px;"><p style="margin:0 0 12px;font-size:14px;color:#64748b;">Your QR entry ticket:</p><a href="${body.qrCodeUrl}" style="display:inline-block;background:#f0fdf4;border:2px dashed #16a34a;color:#16a34a;text-decoration:none;padding:14px 28px;border-radius:10px;font-size:14px;font-weight:700;">📲 View QR Ticket</a></div>` : ''}
    <p style="margin:0;font-size:13px;color:#94a3b8;text-align:center;">Keep this email as your payment receipt. Payment ID is your transaction reference.</p>`
  );

} else if (type === 'attendance_marked') {
  toEmail = body.studentEmail;
  subject = `Attendance Recorded — ${body.eventTitle}`;
  html = base(
    '#7c3aed', '✅', 'Attendance Marked!',
    `${greeting(body.studentName)}
    <p style="margin:0 0 24px;font-size:15px;line-height:1.7;color:#475569;">Your attendance at the following event has been <strong style="color:#7c3aed;">successfully recorded</strong>. Great job showing up!</p>
    <div style="background:#faf5ff;border:1px solid #e9d5ff;border-radius:12px;padding:20px 24px;margin:0 0 28px;">
      <table cellpadding="0" cellspacing="0" style="width:100%;">
        ${infoRow('Event', body.eventTitle)}
        ${infoRow('Club', body.clubName)}
        ${infoRow('Status', '<span style="background:#7c3aed;color:#fff;padding:2px 10px;border-radius:20px;font-size:12px;">Present ✓</span>')}
      </table>
    </div>
    <div style="background:#faf5ff;border:1px solid #e9d5ff;border-radius:12px;padding:20px 24px;margin:0 0 28px;text-align:center;">
      <p style="margin:0 0 4px;font-size:13px;color:#7c3aed;font-weight:600;">PARTICIPATION CERTIFICATE</p>
      <p style="margin:0;font-size:14px;color:#475569;">Your certificate is now available in <strong>My Events</strong> section.</p>
    </div>
    ${divider}
    <div style="text-align:center;">${btn('http://localhost:5173/login', 'Download Certificate', '#7c3aed')}</div>`
  );
}

return [{ json: { toEmail, subject, html, fromEmail: 'no-reply@jadavkeshav.tech' } }];
